class.description:
The same row is always the same [NetwEndpoint], so it can be compared with [code]==[/code] and used as a [Dictionary] key. [codeblock] var endpoint: NetwEndpoint
func bind(row: NetwEndpoint) -> void: endpoint = row endpoint.changed.connect(on_changed) on_changed()
func on_changed() -> void: name_label.text = endpoint.display_name players_label.text = str(endpoint.info.players) dot.modulate = STATUS_COLORS[endpoint.status] [/codeblock]
